package kubernetes_ingress

# Helper predicate: true if a given host string contains a wildcard '*'
function has_wildcard(host: string) bool {
    return host == "*"
}

# Main policy: reject any Ingress that defines a wildcard hostname.
deny_wildcard_host {
    # Find all Ingress objects in the current namespace.
    ingress := input.kubernetes.ingresses[_]

    # Check each rule's host for a wildcard.
    for _, rule := range ingress.spec.rules {
        if has_wildcard(rule.host) {
            # Emit an error indicating which rule violates the policy.
            error := fmt("Ingress %s defines a wildcard hostname '%s' which is prohibited", ingress.metadata.name, rule.host)
            raise error
        }
    }
}
